head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[accordion > P > panelMoveSpeed]<br/>패널이 열리거나 닫힐때 적용되는 애니메이션의 속도를 설정합니다.",
    "validation" : [
        "panelMoveSpeed 속성으로 패널이 열리거나 닫힐 때 적용되는 애니메이션의 속도(지속 시간)를 설정합니다.",
        "panelMoveSpeed 는 Number 타입으로 1~10000 범위의 밀리초(ms) 단위로 애니메이션 지속 시간을 설정합니다.",
        "panelMoveSpeed 로 설정한 시간은 패널 열기/닫기에 동일하게 적용됩니다.",
        "panelMoveSpeed 속성을 생략하면 기본값 500 밀리초가 적용됩니다.",
        "패널 열기 시 panelMoveSpeed 만큼의 애니메이션이 완료된 후 onpanelload 이벤트가 발생합니다.",
        "패널 닫기 시 panelMoveSpeed 만큼의 애니메이션이 완료된 후 onpanelunload 이벤트가 발생합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정 (collapsible=true 로 고정하여 패널 토글 검증 용이)
    let properties = {
        panelMoveSpeed : con_panelMoveSpeed.getValue(),
        collapsible : "true",
    };

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick", "onpanelload", "onpanelunload"]);

    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();

    $c.gcm.createLabel('label="* panelMoveSpeed : 패널 열기/닫기 애니메이션 지속 시간(ms), 1~10000 범위, 기본값 500ms"', '', 'label1');
    $c.gcm.createLabel('label="* 패널 열기 → panelMoveSpeed 시간만큼 슬라이드 애니메이션 후 onpanelload 이벤트 발생"', '', 'label2');
    $c.gcm.createLabel('label="* 패널 닫기 → panelMoveSpeed 시간만큼 슬라이드 애니메이션 후 onpanelunload 이벤트 발생"', '', 'label3');

    strTarget += '<w2:accordion ' + strNameSpace + ' ' + cList + ' ' + eList + ' id="" style="width:240px; height:320px;">';
    strTarget += '<w2:panels style="" id="panels1" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle1" label="panelTitle1"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent1">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel1"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels2" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle2" label="panelTitle2"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent2">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel2"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '<w2:panels style="" id="panels3" class="">';
    strTarget += '<w2:panelTitle style="" id="panelTitle3" label="panelTitle3"></w2:panelTitle>';
    strTarget += '<w2:panelContent style="" id="panelContent3">';
    strTarget += '<w2:button style="width:80px; height:23px;" id="" label="panel3"></w2:button>';
    strTarget += '</w2:panelContent>';
    strTarget += '</w2:panels>';
    strTarget += '</w2:accordion>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "accordion",
        strTarget,
        grp_comp
    );
}



// onclick 핸들러 — panelTitle 클릭 시점 기록 (panelMoveSpeed 적용 시간 측정 시작점)
scwin.target1_onclick = function (panel, open) {
    scwin.__panelClickAt = Date.now();
    wf_body_bottom.getObj("scwin").setReturnValue("[onclick 이벤트 발생] panelMoveSpeed 설정값 = " + target1.options.panelMoveSpeed + "ms");
};



// elapsed 가 설정값 ± margin 내면 성공/벗어나면 실패 (margin = max(100ms, 설정값의 20%))
scwin.judgeElapsed = function (elapsed) {
    let speed = Number(target1.options.panelMoveSpeed) || 500;
    let margin = Math.max(100, Math.round(speed * 0.2));
    let pass = (elapsed >= speed - margin) && (elapsed <= speed + margin);
    return {
        speed : speed,
        margin : margin,
        result : pass ? "성공" : "실패"
    };
};



// onpanelload 핸들러 — 애니메이션 완료 후 발생 (elapsed 측정 후 ± margin 판정)
scwin.target1_onpanelload = function (panelID, userID) {
    if (typeof scwin.__panelClickAt !== "number") {
        wf_body_bottom.getObj("scwin").setReturnValue("[onpanelload 이벤트 발생] elapsed 측정 불가 (onclick 미발생)");
        return;
    }
    let elapsed = Date.now() - scwin.__panelClickAt;
    let r = scwin.judgeElapsed(elapsed);
    wf_body_bottom.getObj("scwin").setReturnValue("[onpanelload 이벤트 발생] elapsed = " + elapsed + "ms (설정값 " + r.speed + "ms ± " + r.margin + "ms) → " + r.result);
};



// onpanelunload 핸들러 — 애니메이션 완료 후 발생 (elapsed 측정 후 ± margin 판정)
scwin.target1_onpanelunload = function (panelID, userID) {
    if (typeof scwin.__panelClickAt !== "number") {
        wf_body_bottom.getObj("scwin").setReturnValue("[onpanelunload 이벤트 발생] elapsed 측정 불가 (onclick 미발생)");
        return;
    }
    let elapsed = Date.now() - scwin.__panelClickAt;
    let r = scwin.judgeElapsed(elapsed);
    wf_body_bottom.getObj("scwin").setReturnValue("[onpanelunload 이벤트 발생] elapsed = " + elapsed + "ms (설정값 " + r.speed + "ms ± " + r.margin + "ms) → " + r.result);
};



// 현재 열린 패널 정보 출력 (getOpenPanelListInfo)
scwin.btn_getOpenPanel_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("===== getOpenPanelListInfo() 결과 =====");
    let openList = target1.getOpenPanelListInfo();
    wf_body_bottom.getObj("scwin").setReturnValue("열린 패널 수 : " + (openList ? openList.length : 0));
    if (openList && openList.length > 0) {
        for (let i = 0; i < openList.length; i++) {
            wf_body_bottom.getObj("scwin").setReturnValue("열린 패널[" + i + "] id : " + openList[i].id);
        }
    } else {
        wf_body_bottom.getObj("scwin").setReturnValue("열린 패널 없음 (모두 닫힘)");
    }
};
